const FB = [[1600, 1620], [1640, 1400], [1720, 1100], [1760, 800], [1700, 550], [1500, 300], [1300, 0]];
const fr1 = frontS({ pts: FA, to: FB, moveT: T_75 - 0.4, moveDur: T_FEW - T_75 + 0.4, sideA: "carth", sideB: "rome", t: 0.2, dur: 1.6, width: +(19.5 / 0.75).toFixed(2), glow: 0.47, until: T_75 + 0.2 });
frontS({ pts: FA, to: FB, moveT: T_75 - 0.4, moveDur: T_FEW - T_75 + 0.4, sideA: "carth", sideB: "rome", t: T_75 - 0.2, dur: 0.01, width: +(19.5 / 1.3).toFixed(2), glow: 0.47, until: END + 1 });

// ---------- places ----------
