boxS("SARTHE", LM[0] - 210, LM[1] + 150, 0.8, T_TOOK, { size: 22, bg: "#dcecf8", sfx: false });

// ---------- XV Corps closes in (units on screen in the first second) ----------
unitS("i90", "carth", [520, 330], "infantry", "90TH", { t: 0.2, size: "XX" });
unitS("i79", "carth", [420, 820], "infantry", "79TH", { t: 0.3, size: "XX" });
