badge({ name: "WADE HAISLIP", role: "XV CORPS", initials: "WH", photo: PHOTO.haislip, flag: FL.us, side: "carth", corner: "br", t: T_MEAN - 0.2, until: T_75 + 0.4 });
B.caption("XV CORPS: FAR BEHIND THEM, TO THE EAST", T_EAST - 0.2, T_NOSTOP - 0.1, "carth");
sstamp("NO STOP · NO LOOKING BACK", 150, T_NOSTOP + 0.1, { color: "#8fb4ff", size: 46, until: T_75 - 0.2, shake: 3 });
